class Alignment(Entity):
    """Alignment (iki/core.Alignment), schema version 2. Sequences aligned, as aligned FASTA, with the ones in Iki linked."""

    IKI_TYPE = 'iki/core.Alignment'

    entity = models.OneToOneField(
        Entity,
        models.PROTECT,
        parent_link=True,
        primary_key=True,
        db_column='entity_id',
        related_name='+',
    )
    name = models.CharField(max_length=200, db_index=True)
    description = models.TextField(null=True)
    reference = models.ForeignKey(Entity, models.PROTECT, related_name='+', null=True)
    aligned = models.ForeignKey(File, models.PROTECT, related_name='+')
    verdict = models.TextField(null=True)
    method = models.CharField(max_length=500, null=True)

    class Meta:
        db_table = 'iki__core_alignment'
        constraints = [
            models.CheckConstraint(
                condition=GreaterThanOrEqual(Length('name'), 1),
                name='iki__core_alignment__name__not_empty',
            ),
            models.CheckConstraint(
                condition=~Q(name__regex='[\\r\\n]'),
                name='iki__core_alignment__name__one_line',
            ),
            models.CheckConstraint(
                condition=GreaterThanOrEqual(Length('description'), 1),
                name='iki__core_alignment__description__not_empty',
            ),
            models.CheckConstraint(
                condition=LessThanOrEqual(Length('description'), 10000),
                name='iki__core_alignment__description__max_length',
            ),
            models.CheckConstraint(
                condition=Q(verdict__in=['matches', 'differs', 'incomplete']),
                name='iki__core_alignment__verdict__values',
            ),
            models.CheckConstraint(
                condition=GreaterThanOrEqual(Length('method'), 1),
                name='iki__core_alignment__method__not_empty',
            ),
            models.CheckConstraint(
                condition=~Q(method__regex='[\\r\\n]'),
                name='iki__core_alignment__method__one_line',
            ),
        ]
        indexes = [
            GinIndex(
                fields=['name'],
                opclasses=['gin_trgm_ops'],
                name='name_trgm_e221cca4261cbd6418a2',
            ),
            GinIndex(
                SearchVector('description', config='simple'),
                name='descriptio_fts_14b467edb18a230',
            ),
        ]


