class View(Entity):
    """View (iki/core.View), schema version 3. A saved look at entities in Iki's viewers, each at the revision it showed."""

    IKI_TYPE = 'iki/core.View'

    entity = models.OneToOneField(
        Entity,
        models.PROTECT,
        parent_link=True,
        primary_key=True,
        db_column='entity_id',
        related_name='+',
    )
    name = models.CharField(max_length=200, db_index=True)
    description = models.TextField(null=True)
    target_revisions = ArrayField(models.BigIntegerField())
    viewers = ArrayField(models.TextField())
    state = models.JSONField()

    class Meta:
        db_table = 'iki__core_view'
        constraints = [
            models.CheckConstraint(
                condition=GreaterThanOrEqual(Length('name'), 1),
                name='iki__core_view__name__not_empty',
            ),
            models.CheckConstraint(
                condition=~Q(name__regex='[\\r\\n]'),
                name='iki__core_view__name__one_line',
            ),
            models.CheckConstraint(
                condition=GreaterThanOrEqual(Length('description'), 1),
                name='iki__core_view__description__not_empty',
            ),
            models.CheckConstraint(
                condition=LessThanOrEqual(Length('description'), 10000),
                name='iki__core_view__description__max_length',
            ),
            models.CheckConstraint(
                condition=checks.IsPlainList('target_revisions'),
                name='iki__core_view__target_revisions__plain_list',
            ),
            models.CheckConstraint(
                condition=Q(target_revisions__len__gte=1),
                name='iki__core_view__target_revisions__min_items',
            ),
            models.CheckConstraint(
                condition=Q(target_revisions__len__lte=20),
                name='iki__core_view__target_revisions__max_items',
            ),
            models.CheckConstraint(
                condition=checks.AllBetweenInt('target_revisions', 1, None),
                name='iki__core_view__target_revisions__item_bounds',
            ),
            models.CheckConstraint(
                condition=checks.IsPlainList('viewers'),
                name='iki__core_view__viewers__plain_list',
            ),
            models.CheckConstraint(
                condition=Q(viewers__len__gte=1),
                name='iki__core_view__viewers__min_items',
            ),
            models.CheckConstraint(
                condition=Q(viewers__len__lte=20),
                name='iki__core_view__viewers__max_items',
            ),
            models.CheckConstraint(
                condition=Q(viewers__contained_by=['sequence', 'structure', 'alignment']),
                name='iki__core_view__viewers__item_values',
            ),
        ]
        indexes = [
            GinIndex(
                fields=['name'],
                opclasses=['gin_trgm_ops'],
                name='name_trgm_69c0d33f7d43bc366ba2',
            ),
            GinIndex(
                SearchVector('description', config='simple'),
                name='descriptio_fts_201bc7bf7161a9c',
            ),
        ]


class View_History(models.Model):
    """The history of iki__core_view: its values at each revision of each entity."""

    IKI_HISTORY_OF = 'View'
    APPEND_ONLY = True

    pk = models.CompositePrimaryKey('entity_id', 'revision')
    entity_id = models.UUIDField()
    revision = models.PositiveIntegerField()
    name = models.TextField(null=True)
    description = models.TextField(null=True)
    target = models.UUIDField(db_column='target_id', null=True)
    target_revision = models.BigIntegerField(null=True)
    viewer = models.TextField(null=True)
    targets = ArrayField(models.UUIDField(), null=True)
    target_revisions = ArrayField(models.BigIntegerField(), null=True)
    viewers = ArrayField(models.TextField(), null=True)
    state = models.JSONField(null=True)

    class Meta:
        db_table = 'iki__core_view__history'


class View_targets(models.Model):
    """The items of iki/core.View.targets, in order."""

    IKI_LIST_OF = ('View', 'targets')

    pk = models.CompositePrimaryKey('entity', 'position')
    entity = models.ForeignKey('View', models.CASCADE, db_column='entity_id', related_name='+')
    position = models.PositiveIntegerField()
    item = models.ForeignKey(Entity, models.PROTECT, related_name='+')

    class Meta:
        db_table = 'iki__core_view__targets'
        constraints = [
            models.CheckConstraint(
                condition=Q(position__lt=20),
                name='iki__core_view__targets__position__max_items',
            ),
        ]
